package com.nigson.commerce.market;
import java.util.*;
import java.time.Clock;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;
import com.nigson.commerce.catalogue.CatalogueMarketChanges;
import com.nigson.commerce.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ActorAssertion;
public final class MarketService {
 private final MarketRepository repository;private final MarketAuthority authority;private final CatalogueMarketChanges catalogue;private final PlatformStore commands;private final AuditWriter audit;private final Clock clock;private final JdbcTemplate jdbc;private final TransactionTemplate reads;private final io.micrometer.core.instrument.MeterRegistry metrics;private final int budget;private long second=-1;private int calls;
 public MarketService(MarketRepository repository,MarketAuthority authority,CatalogueMarketChanges catalogue,PlatformStore commands,AuditWriter audit,Clock clock,JdbcTemplate jdbc,org.springframework.transaction.PlatformTransactionManager manager,io.micrometer.core.instrument.MeterRegistry metrics,int budget){if(budget<1||budget>10000)throw new IllegalArgumentException("MARKET_READ_BUDGET_INVALID");this.repository=repository;this.authority=authority;this.catalogue=catalogue;this.commands=commands;this.audit=audit;this.clock=clock;this.jdbc=jdbc;this.metrics=metrics;this.budget=budget;reads=new TransactionTemplate(manager);reads.setReadOnly(true);reads.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_REPEATABLE_READ);reads.setTimeout(3);}
 private synchronized void admit(){long now=clock.instant().getEpochSecond();if(now!=second){second=now;calls=0;}if(++calls>budget)throw new Problem.Failure(ProblemCode.RATE_LIMITED);}
 public List<MarketValues.PublicMarket> list(){admit();return reads.execute(s->{jdbc.execute("SET LOCAL statement_timeout='1s'");return repository.publicMarkets();});}
 private void input(ActorAssertion.Actor actor,String role,String key,UUID correlation){authority.require(actor,role);ApiValues.idempotencyKey(key);if(correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();}
 private void lock(ActorAssertion.Actor actor,String role){jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");authority.stabilize(actor,role);}
 private void version(long value){if(value<0||value==Long.MAX_VALUE)throw ApiValues.invalid();}
 private PlatformStore.Response execute(ActorAssertion.Actor actor,String api,String key,Object body,java.util.function.Function<JdbcTemplate,PlatformStore.Response> callback){try{return commands.executeLocal(actor.party().toString(),api,key,EventCodec.JSON.valueToTree(body),callback);}catch(org.springframework.dao.DataAccessException failure){for(Throwable cause=failure;cause!=null;cause=cause.getCause())if(cause instanceof java.sql.SQLException sql&&Set.of("55P03","57014").contains(sql.getSQLState()))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_IN_PROGRESS);throw failure;}}
 private void count(String operation){org.springframework.transaction.support.TransactionSynchronizationManager.registerSynchronization(new org.springframework.transaction.support.TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.market.commands","operation",operation).increment();}});}
 public MarketValues.Market create(ActorAssertion.Actor actor,MarketValues.Create value,String key,UUID correlation){input(actor,"FINANCE",key,correlation);var response=execute(actor,"API-169",key,value,db->{lock(actor,"FINANCE");var after=repository.create(value,actor.party().toString());audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.MARKET_CREATE,AuditValues.Resource.MARKET,after.id(),correlation,AuditValues.Reason.CONFIGURATION_CHANGE,null,Map.of("version",after.version(),"revision",after.policyRevision(),"enabled",false,"currency",after.currency()),null);count("CREATE");return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(after),after.id());});return EventCodec.JSON.treeToValue(response.body(),MarketValues.Market.class);}
 public MarketValues.Market update(ActorAssertion.Actor actor,UUID market,long expected,MarketValues.Update value,String key,UUID correlation){input(actor,"ADMIN",key,correlation);version(expected);if(market==null||market.equals(new UUID(0,0)))throw ApiValues.invalid();var response=execute(actor,"API-030",key,Map.of("market",market,"version",expected,"body",value),db->{lock(actor,"ADMIN");var before=repository.find(market,true);if(before.version()!=expected)throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);var after=repository.update(market,expected,value,actor.party().toString());if(!after.equals(before)){audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.MARKET_UPDATE,AuditValues.Resource.MARKET,market,correlation,AuditValues.Reason.CONFIGURATION_CHANGE,Map.of("version",before.version(),"revision",before.policyRevision(),"enabled",before.enabled(),"currency",before.currency()),Map.of("version",after.version(),"revision",after.policyRevision(),"enabled",after.enabled(),"currency",after.currency()),null);event(after,actor.party().toString(),correlation);count("UPDATE");}return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(after),market);});return EventCodec.JSON.treeToValue(response.body(),MarketValues.Market.class);}
 public MarketValues.Restriction restriction(ActorAssertion.Actor actor,UUID product,UUID market,long expected,MarketValues.Eligibility value,String key,UUID correlation){input(actor,"CONTENT_PUBLISHER",key,correlation);version(expected);var response=execute(actor,"API-031",key,Map.of("product",product,"market",market,"version",expected,"body",value),db->{lock(actor,"CONTENT_PUBLISHER");catalogue.lock(product,expected);repository.restriction(product,market,value,actor.party().toString());long next=catalogue.changed(product,actor.party().toString(),correlation);var after=new MarketValues.Restriction(product,market,value.eligible(),next);audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.MARKET_ELIGIBILITY,AuditValues.Resource.PRODUCT,product,correlation,AuditValues.Reason.OPERATOR_REQUEST,Map.of("version",expected),Map.of("version",next,"enabled",value.eligible()),null);count("ELIGIBILITY");return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(after),product);});return EventCodec.JSON.treeToValue(response.body(),MarketValues.Restriction.class);}
 public MarketValues.Market book(ActorAssertion.Actor actor,UUID market,long expected,MarketValues.Book value,String key,UUID correlation){input(actor,"FINANCE",key,correlation);version(expected);var response=execute(actor,"API-162",key,Map.of("market",market,"version",expected,"body",value),db->{lock(actor,"FINANCE");var after=repository.book(market,expected,value,actor.party().toString());audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.MARKET_BOOK,AuditValues.Resource.MARKET,market,correlation,AuditValues.Reason.CONFIGURATION_CHANGE,Map.of("version",expected),Map.of("version",after.version(),"revision",after.policyRevision(),"enabled",after.enabled()),null);event(after,actor.party().toString(),correlation);count("BOOK");return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(after),market);});return EventCodec.JSON.treeToValue(response.body(),MarketValues.Market.class);}
 private void event(MarketValues.Market v,String actor,UUID correlation){var e=new LinkedHashMap<String,Object>();e.put("event_id",EventCodec.uuid7(clock.instant()));e.put("event_type","market.changed.v1");e.put("schema_version",1);e.put("producer","commerce");e.put("occurred_at",clock.instant());e.put("aggregate_id",v.id());e.put("aggregate_version",v.version());e.put("organization_id",null);e.put("correlation_id",correlation);var span=io.opentelemetry.api.trace.Span.current().getSpanContext();e.put("traceparent",span.isValid()?"00-"+span.getTraceId()+"-"+span.getSpanId()+"-"+span.getTraceFlags().asHex():null);e.put("payload",Map.of("market_id",v.id(),"policy_revision",v.policyRevision(),"enabled",v.enabled()));commands.append(EventCodec.JSON.writeValueAsString(e),actor);}
}
